import {clamp,mix,smooth,random,WEATHER} from './core.js';
export class AirFX{
 constructor(){this.canvas=document.getElementById('air');this.ctx=this.canvas.getContext('2d');this.rnd=random(11937);this.particles=Array.from({length:90},()=>this.spawn());this.trails={L:[],R:[]};this.resize()}
 spawn(){const r=this.rnd;let x=r()*2-1,y=r()*2-1;if(Math.hypot(x,y)<.3)x+=x>0?.36:-.36;return {x,y,z:.2+r()*.8,prev:null,life:r(),alpha:.10+r()*.2}}
 reset(){this.trails={L:[],R:[]};for(const p of this.particles)p.prev=null}
 resize(){this.w=innerWidth;this.h=innerHeight;this.ratio=Math.min(devicePixelRatio||1,1.5);this.canvas.width=this.w*this.ratio;this.canvas.height=this.h*this.ratio;this.ctx.setTransform(this.ratio,0,0,this.ratio,0,0)}
 update(s,hands,dt,config){if(dt===0)return;const c=this.ctx,w=this.w,h=this.h;c.clearRect(0,0,w,h);const active=['entry','freefall','opening','canopy'].includes(s.phase);if(!active){this.trails={L:[],R:[]};if(s.phase==='land'&&s.contact&&s.contactTime<.18){c.fillStyle=`rgba(255,244,217,${(1-s.contactTime/.18)*.15})`;c.fillRect(0,0,w,h)}return}
 const speed=(s.flightCue||0)*2.5,ch=s.chute,motion=config.motion?1:.25,rain=WEATHER[config.weather].rain*(1-smooth(4300,6000,s.h));const cx=w*.5,cy=h*.5;
 // Particle depth decreases toward the lens; directions never rotate around the screen.
 c.lineCap='round';for(let i=0;i<this.particles.length;i++){const p=this.particles[i];p.z-=dt*mix(.68,.21,ch)*(.08+speed)*motion;if(p.z<.09)Object.assign(p,this.spawn(),{z:1,prev:null});const scale=.16/Math.max(.08,p.z),x=cx+p.x*w*scale,y=cy+p.y*h*scale;const r=Math.hypot((x-cx)/w,(y-cy)/h),a=p.alpha*smooth(.16,.55,r)*(1-ch*.55)*motion*smooth(.015,.16,s.flightCue||0);if(p.prev&&a>.005){let dx=x-p.prev.x,dy=y-p.prev.y,len=Math.hypot(dx,dy);if(len>80){dx*=80/len;dy*=80/len}const g=c.createLinearGradient(x-dx*2,y-dy*2,x,y);g.addColorStop(0,'rgba(225,250,255,0)');g.addColorStop(1,`rgba(235,252,255,${a})`);c.strokeStyle=g;c.lineWidth=.7+speed*.8;c.beginPath();c.moveTo(x-dx*2,y-dy*2);c.lineTo(x,y);c.stroke()}p.prev={x,y};}
 for(const side of ['L','R']){const a=hands.project(side),sign=side==='L'?-1:1,trail=this.trails[side];if(!a)continue;for(const p of trail){p.age+=dt;p.x+=(p.x-cx)*dt*(.8+speed);p.y+=(p.y-cy)*dt*(.8+speed);}while(trail.length&&trail[0].age>.32)trail.shift();if(s.chute<.6&&dt>0)trail.push({x:a.x,y:a.y,age:0});if(trail.length>2&&ch<.7){c.lineWidth=2;for(let i=1;i<trail.length;i++){const p=trail[i],q=trail[i-1],alpha=(1-p.age/.32)*.29*(1-ch);c.strokeStyle=s.heat>.12?`rgba(255,190,112,${alpha})`:`rgba(213,248,248,${alpha})`;c.beginPath();c.moveTo(q.x,q.y);c.lineTo(p.x,p.y);c.stroke()}}}
 if(rain>0){c.strokeStyle=`rgba(207,232,245,${rain*.23})`;c.lineWidth=1;for(let i=0;i<46;i++){const x=(i*157.3+s.clock*38)%w,y=(i*73.1+s.clock*810)%h,dx=(x-cx)/w*30,dy=(y-cy)/h*30;c.beginPath();c.moveTo(x-dx,y-dy);c.lineTo(x,y);c.stroke()}for(let i=0;i<5;i++){const age=(s.clock*.19+i*.213)%1,x=(.14+i*.183)*w,y=(.1+age*.9)*h;c.strokeStyle=`rgba(238,250,255,${Math.sin(age*Math.PI)*rain*.12})`;c.lineWidth=1.6;c.beginPath();c.ellipse(x,y,2.2,5,0,0,Math.PI*2);c.stroke()}}
 if(config.motion&&['storm','hurricane'].includes(config.weather)&&s.h<5000){const t=s.clock%13.6;if(t<.045||t>.17&&t<.20){c.fillStyle='rgba(220,230,255,.20)';c.fillRect(0,0,w,h)}}
 }
}
